import './page-shell.js';
const contactSnapshotKey = 'oman-tracker-contact-snapshot-v1';
const nativeFetch = window.fetch.bind(window);
window.fetch = async (input, init) => {
  const requestUrl = new URL(typeof input === 'string' ? input : input.url, window.location.href);
  if (requestUrl.pathname !== '/v1/discovery/contacts') return nativeFetch(input, init);
  let snapshot = null;
  try { snapshot = JSON.parse(localStorage.getItem(contactSnapshotKey) || 'null'); } catch {}
  if (snapshot?.snapshotAt) requestUrl.searchParams.set('since', snapshot.snapshotAt);
  const response = await nativeFetch(requestUrl, init);
  if (!response.ok) return response;
  const delta = await response.clone().json();
  const merged = new Map((snapshot?.contacts || []).map(row => [String(row.id), row]));
  for (const row of delta.contacts || []) merged.set(String(row.id), row);
  const contacts = [...merged.values()];
  const nextSnapshot = { snapshotAt: delta.snapshotAt || snapshot?.snapshotAt || new Date().toISOString(), contacts };
  try { localStorage.setItem(contactSnapshotKey, JSON.stringify(nextSnapshot)); } catch {}
  return new Response(JSON.stringify({ ...delta, contacts }), { status: response.status, headers: { 'content-type': 'application/json' } });
};
window.__contactTableEnhanced = true;
const sheet = document.createElement('link'); sheet.rel = 'stylesheet'; sheet.href = '/tracker/contacts.css'; document.head.append(sheet);
const results = document.querySelector('#contacts-results'); const count = document.querySelector('#contacts-count'); const notice = document.querySelector('#contacts-notice');
