function resizeHandle(th,key){const handle=document.createElement('span');handle.className='contact-column-resizer';handle.title=`Drag to resize ${key==='__actions__'?'Actions':label(key)} column`;handle.setAttribute('aria-label',`Resize ${key==='__actions__'?'Actions':label(key)} column`);handle.setAttribute('role','separator');handle.addEventListener('pointerdown',event=>{event.preventDefault();event.stopPropagation();handle.setPointerCapture?.(event.pointerId);const startX=event.clientX;const startWidth=th.getBoundingClientRect().width;document.body.classList.add('resizing-contact-column');const move=moveEvent=>{if(!moveEvent.buttons&&moveEvent.pointerType==='mouse')return;prefs.widths[key]=Math.max(key==='__actions__'?64:90,Math.round(startWidth+moveEvent.clientX-startX));applyWidths()};const stop=()=>{document.body.classList.remove('resizing-contact-column');handle.releasePointerCapture?.(event.pointerId);handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',stop);handle.removeEventListener('pointercancel',stop);save()};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',stop);handle.addEventListener('pointercancel',stop)});return handle}
function applyWidths(){const table=document.querySelector('.contacts-table');if(!table)return;const actionHead=table.tHead?.querySelector('th:first-child');if(actionHead&&!actionHead.querySelector('.contact-column-resizer')){actionHead.className='contact-actions-heading';actionHead.append(resizeHandle(actionHead,'__actions__'))}const actionWidth=prefs.widths.__actions__||82;const actionCol=table.querySelector('.contact-actions-column');if(actionCol){actionCol.style.width=`${actionWidth}px`;actionCol.style.minWidth=`${actionWidth}px`}let total=actionWidth;table.querySelectorAll('col[data-column]').forEach(col=>{const width=prefs.widths[col.dataset.column]||170;col.style.width=`${width}px`;col.style.minWidth=`${width}px`;total+=width});table.style.width=`${total}px`;table.style.minWidth=`${total}px`;queueMicrotask(()=>renderPagination())}
